INSERT INTO `notification` (`id`, `entity_code`, `registered_user_id`, `type`, `title`, `description`, `staus`, `created_by`, `created_at`) VALUES
(1, 'LOADDEMO', 1, 'Message', 'Test Broadcast Message', '<p>This is a <strong>TEST</strong> Broadcast Message</p><figure class=\"table\"><table><tbody><tr><td>#</td><td>Thoughts</td><td>Suggestions</td><td>Actions</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table></figure><p>In case you see this image, Please confirm as <i><strong>YES</strong></i>:</p><ul><li>Test Message</li></ul><ol><li>Test Message</li></ol><h3>This is Sub Heading</h3><h2>This is Main Heading</h2>', 0, 1, '2023-09-11 06:42:25'),
(2, 'LOADDEMO', 1, 'Issue', 'This is Issue Message', '<p>Following ar my Issues:</p><ol><li>Issue 1</li><li>Issue 2</li><li>Issue 3</li></ol><blockquote><p>I need <strong>resulutions</strong> for all above</p></blockquote>', 0, 1, '2023-09-11 06:44:07'),
(3, 'LOADDEMO', 1, 'Issue', 'This is my Issue', '<p>This Issue is from Neena</p><ol><li>A</li><li>B</li><li>C</li><li>w</li></ol>', 0, 4, '2023-09-11 06:46:31'),
(4, 'DLJM', 3, 'Message', 'Test', '<p>test rest</p>', 0, 5, '2024-01-29 11:08:01'),
(5, 'PROBUDS', 8, 'Notification', 'Broadcast Test', '<p>30 Aug 2025</p>', 0, 27, '2025-08-30 05:56:24'),
(6, 'PROBUDS', 8, 'Notification', 'Brodcast Test for Manager', '<p>30 Aug 2025</p>', 0, 27, '2025-08-30 06:00:31'),
(7, 'PROBUDS', 8, 'Notification', 'Broadcast Test For Entity Owner', '<p>Test 30 Aug 2025 (Testing for Message to JS Also)</p>', 0, 27, '2025-08-30 06:02:21'),
(8, 'PROBUDS', 8, 'Notification', 'Brodcast for process owner', '<p>Test 30 Aug 2025 (Testing for Message to JS Also)</p>', 0, 27, '2025-08-30 06:03:05'),
(9, 'PROBUDS', 8, 'Notification', 'Brodcast for Verifier', '<p>Test 30 Aug 2025 (Testing for Message to JS &amp; SK Also)</p>', 0, 27, '2025-08-30 06:03:50'),
(10, 'PROBUDS', 8, 'Notification', 'sdsadasd', '<p>asdasdasdasds</p>', 0, 27, '2025-09-07 06:05:37'),
(11, 'DEMOCO', 6, 'Notification', 'omi', '<p>romii</p>', 0, 24, '2025-10-06 12:47:12'),
(12, 'MILEY', 16, 'Notification', 'Test Broadcast for Verifiers', '<p>Hello Verifier\'s,</p><p>Welcome to the VerifyFA App.</p><p>You are going to do the following:</p><ol><li>Access to projects that are mapped for verification</li><li>Conduct verification by use of Mobile App</li><li>Report the real-time info on project to your superiors</li></ol><p>Good luck!</p>', 0, 42, '2025-10-09 08:26:47'),
(13, 'MILEY', 16, 'Message', 'Test Message for MGR & VRF', '<p>Hello VerfyFA Managers and Verifers,</p><p>&nbsp;</p><p>Welcome!</p><ol><li>Never share your credentials</li><li>Always finish as plan plan</li><li>Always check your work befor end of day</li></ol><p>Thanks !</p>', 0, 42, '2025-10-09 08:45:15'),
(14, 'MILEY', 16, 'Notification', 'Broadcast Msg for MGR & VRF', '<p>Hello VerifyFA MGRs and VRFs,</p><p>This message is a test message</p><ol><li><i>Follow instructions</i></li><li><strong>Complete the assignment</strong></li><li>If you have any issue , tell your Manager by creating Issue through Web App</li></ol><p>&nbsp;</p>', 0, 42, '2025-10-09 11:05:19'),
(15, 'MILEY', 16, 'Notification', 'Broadcast by MGR-JS', '<p>This test message by <strong>Jasmeet as Manager</strong> <i>User Role</i></p>', 0, 43, '2025-10-09 11:14:19'),
(16, 'SHREE', 17, 'Notification', 'Test Broadcast Message for All Users', '<p>Test Broadcast Message for All Users Description</p>', 0, 54, '2025-10-17 11:27:38'),
(17, 'SHREE', 17, 'Notification', 'Test Second Message for All user', '<p>Test Second Message for All user Description</p>', 0, 54, '2025-10-17 11:36:54'),
(18, 'SHREE', 17, 'Notification', 'Manager Test Broadcast for Verify User', '<p>Manager Test Broadcast for Verify User Descriotion</p>', 0, 55, '2025-10-17 11:41:09');
