CREATE TABLE `issue_manage` (
  `id` int(11) NOT NULL,
  `tracking_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issue_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `company_name` int(11) NOT NULL DEFAULT '0',
  `location_name` int(11) NOT NULL DEFAULT '0',
  `project_name` int(11) NOT NULL DEFAULT '0',
  `manage_name` int(11) NOT NULL,
  `groupadmin_name` int(11) NOT NULL DEFAULT '0',
  `issue_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issue_description` text COLLATE utf8mb4_unicode_ci,
  `issue_attachment` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '5c915739a9315cae2468126e9bccfaf0.pdf',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '1 :- Open | 0 :- Closed',
  `status_type` int(11) NOT NULL DEFAULT '1' COMMENT '1 :- New | 2 :- Escalated',
  `remark_content` text COLLATE utf8mb4_unicode_ci,
  `created_by` int(11) NOT NULL DEFAULT '0',
  `resolved_by` int(11) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

